import{_ as t,o,c as d,ap as a}from"./chunks/framework.D5dqwIER.js";const m=JSON.parse('{"title":"API overview","description":"","frontmatter":{},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md","lastUpdated":null}'),s={name:"api/index.md"};function c(l,e,n,r,i,_){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="api-index" tabindex="-1">API overview <a class="header-anchor" href="#api-index" aria-label="Permalink to &quot;API overview {#api-index}&quot;">​</a></h1><p>The public interface, grouped by theme. Every exported name appears on exactly one of the pages below; the last one is a catch-all that lists anything not yet curated, so a newly exported symbol can never go undocumented.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Page</th><th style="text-align:left;">Covers</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./bases">Bases</a></td><td style="text-align:left;">basis types, metric, accessors, <code>init_*</code></td></tr><tr><td style="text-align:left;"><a href="./tensors">Tensors</a></td><td style="text-align:left;"><code>AbstractTens</code>, <code>Tens</code>, components, Kelvin-Mandel</td></tr><tr><td style="text-align:left;"><a href="./structured">Structured tensors</a></td><td style="text-align:left;"><code>TensISO</code> and the isotropic projectors</td></tr><tr><td style="text-align:left;"><a href="./walpole">Walpole and orthotropy</a></td><td style="text-align:left;"><code>TensTI</code>, <code>TensOrtho</code>, parametrizations</td></tr><tr><td style="text-align:left;"><a href="./cubic">Cubic symmetry</a></td><td style="text-align:left;"><code>TensCubic</code>, three constants and a cube frame</td></tr><tr><td style="text-align:left;"><a href="./projection">Projection</a></td><td style="text-align:left;"><code>proj_tens</code>, <code>best_sym_tens</code>, predicates</td></tr><tr><td style="text-align:left;"><a href="./special">Special tensors</a></td><td style="text-align:left;">Levi-Civita, rotations, unit vectors</td></tr><tr><td style="text-align:left;"><a href="./coorsystems">Coordinate systems</a></td><td style="text-align:left;"><code>CoordinateSystem</code>, its exact geometry and the operators</td></tr><tr><td style="text-align:left;"><a href="./coorsystems_num">Numerical coordinate systems</a></td><td style="text-align:left;"><code>PointwiseGeometry</code></td></tr><tr><td style="text-align:left;"><a href="./submanifold">Submanifolds</a></td><td style="text-align:left;"><code>Submanifold</code> and its accessors</td></tr><tr><td style="text-align:left;"><a href="./symbolic">Symbolic helpers</a></td><td style="text-align:left;"><code>tsimplify</code>, <code>tsubs</code>, and the array algebra</td></tr><tr><td style="text-align:left;"><a href="./full_index">Full index</a></td><td style="text-align:left;">everything, alphabetically</td></tr></tbody></table><h2 id="api-renamed-0-8" tabindex="-1">Renamed in 0.8 <a class="header-anchor" href="#api-renamed-0-8" aria-label="Permalink to &quot;Renamed in 0.8 {#api-renamed-0-8}&quot;">​</a></h2><p>TensND 0.8 names its functions as Julia does: lowercase, a proper name included, as <code>cholesky</code> or <code>schur</code> in LinearAlgebra; types keep their capitals. The former names still work and warn once, naming their successor; they will be removed in a later minor release. The moduli keep their symbols as exact aliases, without a warning.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Former name</th><th style="text-align:left;">Name in 0.8</th></tr></thead><tbody><tr><td style="text-align:left;"><code>KM</code>, <code>inv_KM</code></td><td style="text-align:left;"><a href="/TensND.jl/dev/api/tensors#TensND.mandel"><code>mandel</code></a>, <a href="/TensND.jl/dev/api/tensors#TensND.from_mandel"><code>from_mandel</code></a></td></tr><tr><td style="text-align:left;"><code>KM_material</code>, <code>KM_rotation</code></td><td style="text-align:left;"><a href="/TensND.jl/dev/api/walpole#TensND.mandel_material"><code>mandel_material</code></a>, <a href="/TensND.jl/dev/api/tensors#TensND.mandel_rotation"><code>mandel_rotation</code></a></td></tr><tr><td style="text-align:left;"><code>KM_from_ti_params</code>, <code>KM_from_ti8_params</code>, <code>KM_from_ortho_params</code>, <code>KM_from_cubic_params</code></td><td style="text-align:left;"><code>mandel_from_ti_params</code>, <code>mandel_from_ti8_params</code>, <code>mandel_from_ortho_params</code>, <code>mandel_from_cubic_params</code></td></tr><tr><td style="text-align:left;"><code>ti_params_from_KM</code>, <code>ti8_params_from_KM</code>, <code>ortho_params_from_KM</code>, <code>cubic_params_from_KM</code></td><td style="text-align:left;"><code>ti_params_from_mandel</code>, <code>ti8_params_from_mandel</code>, <code>ortho_params_from_mandel</code>, <code>cubic_params_from_mandel</code></td></tr><tr><td style="text-align:left;"><code>KM_IP</code>, <code>KM_OP</code> (constants)</td><td style="text-align:left;"><a href="/TensND.jl/dev/api/tensors#TensND.MANDEL_IP"><code>MANDEL_IP</code></a>, <a href="/TensND.jl/dev/api/tensors#TensND.MANDEL_OP"><code>MANDEL_OP</code></a></td></tr><tr><td style="text-align:left;"><code>km_ip_block</code>, <code>km_op_block</code>, <code>km_ip_embed</code>, <code>km_op_embed</code>, <code>km_from_blocks</code>, <code>km_inv_schur</code></td><td style="text-align:left;"><code>mandel_ip_block</code>, <code>mandel_op_block</code>, <code>mandel_ip_embed</code>, <code>mandel_op_embed</code>, <code>mandel_from_blocks</code>, <code>mandel_inv_schur</code></td></tr><tr><td style="text-align:left;"><code>is_ISO</code>, <code>is_TI</code>, <code>is_ORTHO</code>, <code>is_CUBIC</code></td><td style="text-align:left;"><a href="/TensND.jl/dev/api/projection#TensND.isisotropic"><code>isisotropic</code></a>, <a href="/TensND.jl/dev/api/projection#TensND.istransverselyisotropic"><code>istransverselyisotropic</code></a>, <a href="/TensND.jl/dev/api/projection#TensND.isorthotropic"><code>isorthotropic</code></a>, <a href="/TensND.jl/dev/api/projection#TensND.iscubic"><code>iscubic</code></a></td></tr><tr><td style="text-align:left;"><code>tens_TI</code>, <code>tens_TI_eng</code>, <code>tens_TI_Hoenig</code></td><td style="text-align:left;"><a href="/TensND.jl/dev/api/walpole#TensND.tens_ti"><code>tens_ti</code></a>, <a href="/TensND.jl/dev/api/walpole#TensND.tens_ti_eng"><code>tens_ti_eng</code></a>, <a href="/TensND.jl/dev/api/walpole#TensND.tens_ti_hoenig"><code>tens_ti_hoenig</code></a></td></tr><tr><td style="text-align:left;"><code>arg_TI</code>, <code>arg_TI_eng</code>, <code>arg_TI_Hoenig</code></td><td style="text-align:left;"><a href="/TensND.jl/dev/api/walpole#TensND.ti_args"><code>ti_args</code></a>, <a href="/TensND.jl/dev/api/walpole#TensND.ti_args_eng"><code>ti_args_eng</code></a>, <a href="/TensND.jl/dev/api/walpole#TensND.ti_args_hoenig"><code>ti_args_hoenig</code></a></td></tr><tr><td style="text-align:left;"><code>fromISO</code></td><td style="text-align:left;"><a href="/TensND.jl/dev/api/walpole#TensND.iso_to_ti"><code>iso_to_ti</code></a></td></tr><tr><td style="text-align:left;"><code>ISO</code>, <code>Walpole</code></td><td style="text-align:left;"><a href="/TensND.jl/dev/api/structured#TensND.iso_projectors"><code>iso_projectors</code></a>, <a href="/TensND.jl/dev/api/walpole#TensND.walpole_basis"><code>walpole_basis</code></a> (or <a href="/TensND.jl/dev/api/walpole#TensND.walpole_basis_sym"><code>walpole_basis_sym</code></a> for <code>sym = true</code>)</td></tr><tr><td style="text-align:left;"><code>LeviCivita</code></td><td style="text-align:left;"><a href="/TensND.jl/dev/api/special#TensND.levi_civita"><code>levi_civita</code></a></td></tr><tr><td style="text-align:left;"><code>Christoffel</code>, <code>Lame</code>, <code>getOM</code></td><td style="text-align:left;"><a href="/TensND.jl/dev/api/coorsystems#TensND.christoffel"><code>christoffel</code></a>, <a href="/TensND.jl/dev/api/coorsystems#TensND.lame_coefficients"><code>lame_coefficients</code></a>, <a href="/TensND.jl/dev/api/coorsystems#TensND.position_vector"><code>position_vector</code></a></td></tr><tr><td style="text-align:left;"><code>GRAD</code>, <code>SYMGRAD</code>, <code>DIV</code>, <code>LAPLACE</code>, <code>HESS</code></td><td style="text-align:left;"><a href="/TensND.jl/dev/api/coorsystems#TensND.grad"><code>grad</code></a>, <a href="/TensND.jl/dev/api/coorsystems#TensND.symgrad"><code>symgrad</code></a>, <a href="/TensND.jl/dev/api/coorsystems#Tensors.divergence"><code>divergence</code></a>, <a href="/TensND.jl/dev/api/coorsystems#TensND.laplacian"><code>laplacian</code></a>, <a href="/TensND.jl/dev/api/coorsystems#TensND.hess"><code>hess</code></a></td></tr><tr><td style="text-align:left;"><code>CoorSystemSym</code>, <code>CoorSystemNum</code> (types and constructors)</td><td style="text-align:left;"><a href="/TensND.jl/dev/api/coorsystems#TensND.CoordinateSystem"><code>CoordinateSystem</code></a>, of an <a href="/TensND.jl/dev/api/coorsystems#TensND.ExactGeometry"><code>ExactGeometry</code></a> or a <a href="/TensND.jl/dev/api/coorsystems_num#TensND.PointwiseGeometry"><code>PointwiseGeometry</code></a></td></tr><tr><td style="text-align:left;"><code>coorsys_cartesian_num</code>, <code>coorsys_polar_num</code>, <code>coorsys_cylindrical_num</code>, <code>coorsys_spherical_num</code></td><td style="text-align:left;"><code>coorsys_cartesian(PointwiseGeometry)</code>, … (with an optional element type, <code>coorsys_polar(PointwiseGeometry, Float32)</code>)</td></tr><tr><td style="text-align:left;"><code>SubManifoldSym</code></td><td style="text-align:left;"><a href="/TensND.jl/dev/api/submanifold#TensND.Submanifold"><code>Submanifold</code></a></td></tr><tr><td style="text-align:left;"><code>E_nu</code>, <code>k_mu</code>, <code>mu_nu</code>, <code>iso_stiffness_E_nu</code></td><td style="text-align:left;"><a href="/TensND.jl/dev/api/structured#TensND.young_poisson"><code>young_poisson</code></a>, <a href="/TensND.jl/dev/api/structured#TensND.bulk_shear"><code>bulk_shear</code></a>, <a href="/TensND.jl/dev/api/structured#TensND.shear_poisson"><code>shear_poisson</code></a>, <a href="/TensND.jl/dev/api/structured#TensND.iso_stiffness_young_poisson"><code>iso_stiffness_young_poisson</code></a>; the former names stay as aliases</td></tr></tbody></table><p><code>divergence</code> is Tensors.jl&#39;s function, extended to the coordinate systems, so that <code>using TensND, Tensors</code> leaves one <code>divergence</code>. The Hessian is <code>hess</code>, not <code>hessian</code>: SymPy, which TensND loads, exports a <code>hessian</code> of its own, and the same name would have made <code>using TensND, SymPy</code> ambiguous.</p>',7)])])}const p=t(s,[["render",c]]);export{m as __pageData,p as default};
